using System;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace RioLimpioAdventure.Mechanics
{
    public class WasteInspectionMachine : MonoBehaviour
    {
        // Generated by AI
        [Header("Game Mode Settings")]
        [Tooltip("When enabled, activates the arcade time-attack mode with speed pressure. When disabled, plays in a relaxed educational mode (UDL compliant).")]
        [SerializeField] private bool isTimeAttackMode = false;

        [Header("Timer & Difficulty Settings")]
        [SerializeField] private float baseDecisionTime = 8.0f;
        [SerializeField] private float minDecisionTime = 2.5f;
        [SerializeField] private float speedAccelerationFactor = 0.15f;

        [Header("Accessible UI References (WCAG 2.2)")]
        [SerializeField] private Slider countdownSlider;
        [SerializeField] private Image sliderFillImage;
        [SerializeField] private GameObject dangerAlertOverlay;
        [SerializeField] private TextMeshProUGUI timerWarningText;

        [Header("Color Palette (High Contrast)")]
        [SerializeField] private Color safeColor = new Color(0.18f, 0.80f, 0.44f);
        [SerializeField] private Color warningColor = new Color(0.95f, 0.77f, 0.06f);
        [SerializeField] private Color dangerColor = new Color(0.91f, 0.30f, 0.24f);

        private float currentMaxTime;
        private float remainingTime;
        private int currentStreak = 0;
        private bool isRunning = false;

        public event Action OnTimeExpired;
        public event Action<int, int> OnBonusCalculated;

        private void Update()
        {
            if (!isRunning) return;

            // In relaxed educational mode, we don't force a strict time-out penalty unless Time Attack is active
            if (!isTimeAttackMode) return;

            remainingTime -= Time.deltaTime;
            UpdateTimerVisuals();

            if (remainingTime <= 0f)
            {
                HandleTimeout();
            }
        }

        public void StartInspectionCycle(int itemsProcessed)
        {
            currentMaxTime = Mathf.Max(minDecisionTime, baseDecisionTime - (itemsProcessed * speedAccelerationFactor));
            remainingTime = currentMaxTime;
            isRunning = true;

            if (dangerAlertOverlay != null) dangerAlertOverlay.SetActive(false);
            
            // If Time Attack is disabled, hide the timer slider to reduce cognitive stress for children
            if (countdownSlider != null)
            {
                countdownSlider.gameObject.SetActive(isTimeAttackMode);
            }
        }

        private void UpdateTimerVisuals()
        {
            if (!isTimeAttackMode) return;

            float normalizedTime = Mathf.Clamp01(remainingTime / currentMaxTime);
            if (countdownSlider != null) countdownSlider.value = normalizedTime;

            if (sliderFillImage != null)
            {
                sliderFillImage.color = normalizedTime > 0.5f
                    ? Color.Lerp(warningColor, safeColor, (normalizedTime - 0.5f) * 2f)
                    : Color.Lerp(dangerColor, warningColor, normalizedTime * 2f);
            }

            // Redundant visual alert for accessibility (WCAG 2.2)
            bool isDanger = normalizedTime <= 0.25f;
            if (dangerAlertOverlay != null) dangerAlertOverlay.SetActive(isDanger);
            if (timerWarningText != null)
            {
                timerWarningText.gameObject.SetActive(isDanger);
                timerWarningText.text = isDanger ? "HURRY UP! TIME LOW" : string.Empty;
            }
        }

        public void RegisterSuccessfulClassification()
        {
            isRunning = false;
            currentStreak++;
            
            int speedBonus = isTimeAttackMode ? Mathf.RoundToInt((remainingTime / currentMaxTime) * 100f) : 50;
            int totalAwarded = speedBonus * Mathf.Clamp(currentStreak, 1, 5);
            
            OnBonusCalculated?.Invoke(totalAwarded, currentStreak);
        }

        private void HandleTimeout()
        {
            if (!isTimeAttackMode) return;

            isRunning = false;
            currentStreak = 0;
            if (dangerAlertOverlay != null) dangerAlertOverlay.SetActive(false);
            OnTimeExpired?.Invoke();
        }

        public void SetTimeAttackMode(bool activeState)
        {
            isTimeAttackMode = activeState;
        }
        // End of Generated by AI
    }
}